import math

class DataStatistics4:

    @staticmethod
    def _mean(data):
        return sum(data) / len(data)

    @staticmethod
    def _variance(data, mean):
        return sum((x - mean) ** 2 for x in data) / len(data)

    @staticmethod
    def _std_deviation(data, mean):
        return math.sqrt(DataStatistics4._variance(data, mean))

    @staticmethod
    def correlation_coefficient(data1, data2):
        n = len(data1)
        mean1 = DataStatistics4._mean(data1)
        mean2 = DataStatistics4._mean(data2)

        numerator = DataStatistics4._covariance_numerator(data1, data2, mean1, mean2, n)
        denominator = DataStatistics4._covariance_denominator(data1, data2, mean1, mean2, n)

        if denominator == 0:
            return 0
        return numerator / denominator

    @staticmethod
    def _covariance_numerator(data1, data2, mean1, mean2, n):
        return sum((data1[i] - mean1) * (data2[i] - mean2) for i in range(n))

    @staticmethod
    def _covariance_denominator(data1, data2, mean1, mean2, n):
        sd1 = DataStatistics4._std_deviation(data1, mean1)
        sd2 = DataStatistics4._std_deviation(data2, mean2)
        return n * sd1 * sd2

    @staticmethod
    def skewness(data):
        n = len(data)
        if n < 3:
            return 0
        mean = DataStatistics4._mean(data)
        std_deviation = DataStatistics4._std_deviation(data, mean)
        if std_deviation == 0:
            return 0
        return DataStatistics4._skewness_value(data, mean, std_deviation, n)

    @staticmethod
    def _skewness_value(data, mean, std_deviation, n):
        sum_cubed = sum((x - mean) ** 3 for x in data)
        return sum_cubed * n / ((n - 1) * (n - 2) * std_deviation ** 3)

    @staticmethod
    def kurtosis(data):
        n = len(data)
        if n == 0:
            return math.nan
        mean = DataStatistics4._mean(data)
        std_dev = DataStatistics4._std_deviation(data, mean)
        if std_dev == 0:
            return math.nan
        return DataStatistics4._excess_kurtosis(data, mean, std_dev, n)

    @staticmethod
    def _excess_kurtosis(data, mean, std_dev, n):
        centered_data = [x - mean for x in data]
        fourth_moment = sum(x ** 4 for x in centered_data) / n
        return (fourth_moment / std_dev ** 4) - 3

    @staticmethod
    def pdf(data, mu, sigma):
        if sigma == 0:
            return []
        return [DataStatistics4._pdf_value(x, mu, sigma) for x in data]

    @staticmethod
    def _pdf_value(x, mu, sigma):
        coefficient = 1 / (sigma * math.sqrt(2 * math.pi))
        exponent = -0.5 * ((x - mu) / sigma) ** 2
        return coefficient * math.exp(exponent)
